codeExamples.code:
let single = 'Hello';
let double = "Hello";
let backtick = `Hello`;

console.log(single === double);       // true
console.log(single === backtick);     // true

let length = "JavaScript".length;
console.log(length);                  // 10

function doubleIfNumber(value) {
  if (typeof value !== "number") {
    return "Please provide a number";
  }
  return value * 2;
}

console.log(doubleIfNumber(5));       // 10
console.log(doubleIfNumber("hello")); // "Please provide a number"
console.log(doubleIfNumber(null));    // "Please provide a number"

const population = 7_900_000_000;
const speedOfLight = 299_792_458;
const pi = 3.141_592_653;

console.log(population);     // 7900000000
console.log(speedOfLight);   // 299792458
console.log(pi);             // 3.141592653

// The value is identical — underscores are just visual
console.log(1_000 === 1000); // true

const white = 0xFF_FF_FF;
const mask = 0b1111_0000_1010;
const octal = 0o77_77;

console.log(white);    // 16777215
console.log(mask);     // 3850
console.log(octal);    // 4095

let name = "Vishnu";
let age = 25;

let greeting = `Hello, ${name}!`;
let info = `${name} is ${age} years old.`;

console.log(greeting);  // "Hello, Vishnu!"
console.log(info);      // "Vishnu is 25 years old."

// With concatenation (the old way):
let old = "Hello, " + name + "!";
console.log(old);       // "Hello, Vishnu!"

let price = 49;
let quantity = 3;
let total = `Total: $${price * quantity}`;
console.log(total);  // "Total: $147"

let html = `
  <div class="card">
    <h2>${"User Profile"}</h2>
    <p>Age: ${age}</p>
  </div>
`;
console.log(html);
